const ProjectBranchingModelSchema = ObjectSchema.and(
  z
    .looseObject({
      branch_types: z
        .array(
          z
            .strictObject({
              kind: z
                .enum(['feature', 'bugfix', 'release', 'hotfix'])
                .openapi({ description: 'The kind of branch.' }),
              prefix: z
                .string()
                .openapi({
                  description:
                    'The prefix for this branch type. A branch with this prefix will be classified as per `kind`. The prefix must be a valid prefix for a branch and must always exist. It cannot be blank, empty or `null`.',
                }),
            })
            .openapi({ required: ['kind', 'prefix'] }),
        )
        .min(0)
        .max(4)
        .superRefine((items, ctx) => {
          const seen = new Map()
          for (const [i, val] of items.entries()) {
            const key = JSON.stringify(val)
            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
            else seen.set(key, i)
          }
        })
        .exactOptional()
        .openapi({ description: 'The active branch types.' }),
      development: z
        .strictObject({
          name: z
            .string()
            .openapi({
              description:
                'Name of the target branch. If inherited by a repository, it will default to the main branch if the specified branch does not exist.',
            }),
          use_mainbranch: z
            .boolean()
            .openapi({
              description:
                'Indicates if the setting points at an explicit branch (`false`) or tracks the main branch (`true`).',
            }),
        })
        .exactOptional()
        .openapi({ required: ['name', 'use_mainbranch'] }),
      production: z
        .strictObject({
          name: z
            .string()
            .openapi({
              description:
                'Name of the target branch. If inherited by a repository, it will default to the main branch if the specified branch does not exist.',
            }),
          use_mainbranch: z
            .boolean()
            .openapi({
              description:
                'Indicates if the setting points at an explicit branch (`false`) or tracks the main branch (`true`).',
            }),
        })
        .exactOptional()
        .openapi({ required: ['name', 'use_mainbranch'] }),
    })
    .openapi({
      description: "A project's branching model",
      title: 'Project Branching Model',
      required: [],
    }),
).openapi('ProjectBranchingModel')

