export const getAddonLinkersLinkerKeyValuesValueIdRoute = createRoute({
  method: 'get',
  path: '/addon/linkers/{linker_key}/values/{value_id}',
  tags: ['Addon'],
  summary: 'Get a linker value',
  description:
    'Get a single [linker](/cloud/bitbucket/modules/linker/) value\nof the authenticated application.',
  request: {
    params: z.object({
      linker_key: z
        .string()
        .openapi({
          param: {
            description:
              'The unique key of a [linker module](/cloud/bitbucket/modules/linker/)\nas defined in an application descriptor.',
            in: 'path',
            name: 'linker_key',
            required: true,
            schema: { type: 'string' },
          },
        }),
      value_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The numeric ID of the linker value.',
            in: 'path',
            name: 'value_id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Successful.' },
    401: {
      description: 'Authentication must use app JWT',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description: 'The linker value does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: [] }, { basic: [] }, { api_key: [] }],
})

