export const getHookEventsRoute = createRoute({
  method: 'get',
  path: '/hook_events',
  tags: ['Webhooks'],
  summary: 'Get a webhook resource',
  description:
    'Returns the webhook resource or subject types on which webhooks can\nbe registered.\n\nEach resource/subject type contains an `events` link that returns the\npaginated list of specific events each individual subject type can\nemit.\n\nThis endpoint is publicly accessible and does not require\nauthentication or scopes.\n\nExample:\n\n```\n$ curl https://api.bitbucket.org/2.0/hook_events\n\n{\n    "repository": {\n        "links": {\n            "events": {\n                "href": "https://api.bitbucket.org/2.0/hook_events/repository"\n            }\n        }\n    },\n    "workspace": {\n        "links": {\n            "events": {\n                "href": "https://api.bitbucket.org/2.0/hook_events/workspace"\n            }\n        }\n    }\n}\n```',
  responses: {
    200: {
      description: 'A mapping of resource/subject types pointing to their individual event types.',
      content: { 'application/json': { schema: SubjectTypesSchema } },
    },
  },
  security: [{ oauth2: [] }, { basic: [] }, { api_key: [] }],
})

export const getHookEventsSubjectTypeRoute = createRoute({
  method: 'get',
  path: '/hook_events/{subject_type}',
  tags: ['Webhooks'],
  summary: 'List subscribable webhook types',
  description:
    'Returns a paginated list of all valid webhook events for the\nspecified entity.\n**The team and user webhooks are deprecated, and you should use workspace instead.\nFor more information, see [the announcement](https://developer.atlassian.com/cloud/bitbucket/bitbucket-api-teams-deprecation/).**\n\nThis is public data that does not require any scopes or authentication.\n\nExample:\n\nNOTE: The following example is a truncated response object for the `workspace` `subject_type`.\nWe return the same structure for the other `subject_type` objects.\n\n```\n$ curl https://api.bitbucket.org/2.0/hook_events/workspace\n{\n    "page": 1,\n    "pagelen": 30,\n    "size": 21,\n    "values": [\n        {\n            "category": "Repository",\n            "description": "Whenever a repository push occurs",\n            "event": "repo:push",\n            "label": "Push"\n        },\n        {\n            "category": "Repository",\n            "description": "Whenever a repository fork occurs",\n            "event": "repo:fork",\n            "label": "Fork"\n        },\n        {\n            "category": "Repository",\n            "description": "Whenever a repository import occurs",\n            "event": "repo:imported",\n            "label": "Import"\n        },\n        ...\n        {\n            "category":"Pull Request",\n            "label":"Approved",\n            "description":"When someone has approved a pull request",\n            "event":"pullrequest:approved"\n        },\n    ]\n}\n```',
  request: {
    params: z.object({
      subject_type: z
        .enum(['repository', 'workspace'])
        .openapi({
          param: {
            description: 'A resource or subject type.',
            in: 'path',
            name: 'subject_type',
            required: true,
            schema: { enum: ['repository', 'workspace'], type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A paginated list of webhook types available to subscribe on.',
      content: { 'application/json': { schema: PaginatedHookEventsSchema } },
    },
    404: {
      description: 'If an invalid `{subject_type}` value was specified.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: [] }, { basic: [] }, { api_key: [] }],
})

export const getPullrequestsSelectedUserRoute = createRoute({
  method: 'get',
  path: '/pullrequests/{selected_user}',
  tags: ['Pullrequests'],
  summary: 'List pull requests for a user',
  description:
    'Returns all pull requests authored by the specified user.\n\nBy default only open pull requests are returned. This can be controlled\nusing the `state` query parameter. To retrieve pull requests that are\nin one of multiple states, repeat the `state` parameter for each\nindividual state.\n\nThis endpoint also supports filtering and sorting of the results. See\n[filtering and sorting](/cloud/bitbucket/rest/intro/#filtering) for more details.',
  request: {
    params: z.object({
      selected_user: z
        .string()
        .openapi({
          param: {
            description:
              "This can either be the username of the pull request author, the author's UUID\nsurrounded by curly-braces, for example: `{account UUID}`, or the author's Atlassian ID.\n",
            in: 'path',
            name: 'selected_user',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      state: z
        .enum(['OPEN', 'MERGED', 'DECLINED', 'SUPERSEDED'])
        .exactOptional()
        .openapi({
          param: {
            description:
              'Only return pull requests that are in this state. This parameter can be repeated.',
            in: 'query',
            name: 'state',
            schema: { enum: ['OPEN', 'MERGED', 'DECLINED', 'SUPERSEDED'], type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'All pull requests authored by the specified user.',
      content: { 'application/json': { schema: PaginatedPullrequestsSchema } },
    },
    404: {
      description: 'If the specified user does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['pullrequest'] }, { basic: [] }, { api_key: [] }],
})

export const getRepositoriesRoute = createRoute({
  method: 'get',
  path: '/repositories',
  tags: ['Repositories'],
  summary: 'List public repositories',
  description:
    'Returns a paginated list of all public repositories.\n\nThis endpoint also supports filtering and sorting of the results. See\n[filtering and sorting](/cloud/bitbucket/rest/intro/#filtering) for more details.',
  request: {
    query: z.object({
      after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter the results to include only repositories created on or\nafter this [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601)\n timestamp. Example: `YYYY-MM-DDTHH:mm:ss.sssZ`',
            in: 'query',
            name: 'after',
            required: false,
            schema: { type: 'string' },
          },
        }),
      role: z
        .enum(['admin', 'contributor', 'member', 'owner'])
        .exactOptional()
        .openapi({
          param: {
            description:
              "Filters the result based on the authenticated user's role on each repository.\n\n* **member**: returns repositories to which the user has explicit read access\n* **contributor**: returns repositories to which the user has explicit write access\n* **admin**: returns repositories to which the user has explicit administrator access\n* **owner**: returns all repositories owned by the current user\n",
            in: 'query',
            name: 'role',
            required: false,
            schema: { enum: ['admin', 'contributor', 'member', 'owner'], type: 'string' },
          },
        }),
      q: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Query string to narrow down the response as per [filtering and sorting](/cloud/bitbucket/rest/intro/#filtering).\n`role` parameter must also be specified.\n',
            in: 'query',
            name: 'q',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Field by which the results should be sorted as per [filtering and sorting](/cloud/bitbucket/rest/intro/#filtering).\n',
            in: 'query',
            name: 'sort',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'All public repositories.',
      content: { 'application/json': { schema: PaginatedRepositoriesSchema } },
    },
  },
  security: [{ oauth2: ['repository'] }, { basic: [] }, { api_key: [] }],
})

