export const getRepositoriesWorkspaceRepoSlugPullrequestsPullRequestIdRoute = createRoute({
  method: 'get',
  path: '/repositories/{workspace}/{repo_slug}/pullrequests/{pull_request_id}',
  tags: ['Pullrequests'],
  summary: 'Get a pull request',
  description: 'Returns the specified pull request.',
  request: {
    params: z.object({
      pull_request_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The id of the pull request.',
            in: 'path',
            name: 'pull_request_id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            in: 'path',
            name: 'repo_slug',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            in: 'path',
            name: 'workspace',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The pull request object',
      content: { 'application/json': { schema: PullrequestSchema } },
    },
    401: { description: 'If the repository is private and the request was not authenticated.' },
    404: {
      description: 'If the repository or pull request does not exist',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['pullrequest'] }, { basic: [] }, { api_key: [] }],
})

export const putRepositoriesWorkspaceRepoSlugPullrequestsPullRequestIdRoute = createRoute({
  method: 'put',
  path: '/repositories/{workspace}/{repo_slug}/pullrequests/{pull_request_id}',
  tags: ['Pullrequests'],
  summary: 'Update a pull request',
  description:
    "Mutates the specified pull request.\n\nThis can be used to change the pull request's branches or description.\n\nOnly open pull requests can be mutated.",
  request: {
    params: z.object({
      pull_request_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: 'The id of the pull request.',
            in: 'path',
            name: 'pull_request_id',
            required: true,
            schema: { type: 'integer' },
          },
        }),
      repo_slug: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            in: 'path',
            name: 'repo_slug',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            in: 'path',
            name: 'workspace',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      description: 'The pull request that is to be updated.',
      content: { 'application/json': { schema: PullrequestSchema } },
    },
  },
  responses: {
    200: {
      description: 'The updated pull request',
      content: { 'application/json': { schema: PullrequestSchema } },
    },
    400: {
      description: 'If the input document was invalid.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    401: {
      description: 'If the request was not authenticated.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description: 'If the repository or pull request id does not exist',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['pullrequest:write'] }, { basic: [] }, { api_key: [] }],
})

