export const postRepositoriesWorkspaceRepoSlugRefsBranchesRoute = createRoute({
  method: 'post',
  path: '/repositories/{workspace}/{repo_slug}/refs/branches',
  tags: ['Refs'],
  summary: 'Create a branch',
  description:
    'Creates a new branch in the specified repository.\n\nThe payload of the POST should consist of a JSON document that\ncontains the name of the tag and the target hash.\n\n```\ncurl https://api.bitbucket.org/2.0/repositories/seanfarley/hg/refs/branches \\\n-s -u seanfarley -X POST -H "Content-Type: application/json" \\\n-d \'{\n    "name" : "smf/create-feature",\n    "target" : {\n        "hash" : "default",\n    }\n}\'\n```\n\nThis call requires authentication. Private repositories require the\ncaller to authenticate with an account that has appropriate\nauthorization.\n\nThe branch name should not include any prefixes (e.g.\nrefs/heads). This endpoint does support using short hash prefixes for\nthe commit hash, but it may return a 400 response if the provided\nprefix is ambiguous. Using a full commit hash is the preferred\napproach.',
  request: {
    params: z.object({
      repo_slug: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the repository slug or the UUID of the repository,\nsurrounded by curly-braces, for example: `{repository UUID}`.\n',
            in: 'path',
            name: 'repo_slug',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            in: 'path',
            name: 'workspace',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    201: {
      description: 'The newly created branch object.',
      content: { 'application/json': { schema: BranchSchema } },
    },
    403: {
      description:
        'If the repository is private and the authenticated user does not have\naccess to it.\n',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description: 'The specified repository or branch does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['repository:write'] }, { basic: [] }, { api_key: [] }],
})

