export const getSnippetsWorkspaceEncodedIdRevisionDiffRoute = createRoute({
  method: 'get',
  path: '/snippets/{workspace}/{encoded_id}/{revision}/diff',
  tags: ['Snippets'],
  summary: 'Get snippet changes between versions',
  description:
    "Returns the diff of the specified commit against its first parent.\n\nNote that this resource is different in functionality from the `patch`\nresource.\n\nThe differences between a diff and a patch are:\n\n* patches have a commit header with the username, message, etc\n* diffs support the optional `path=foo/bar.py` query param to filter the\n  diff to just that one file diff (not supported for patches)\n* for a merge, the diff will show the diff between the merge commit and\n  its first parent (identical to how PRs work), while patch returns a\n  response containing separate patches for each commit on the second\n  parent's ancestry, up to the oldest common ancestor (identical to\n  its reachability).\n\nNote that the character encoding of the contents of the diff is\nunspecified as Git does not track this, making it hard for\nBitbucket to reliably determine this.",
  request: {
    params: z.object({
      encoded_id: z
        .string()
        .openapi({
          param: {
            description: 'The snippet id.',
            in: 'path',
            name: 'encoded_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      revision: z
        .string()
        .openapi({
          param: {
            description:
              'A revspec expression. This can simply be a commit SHA1, a ref name, or a compare expression like `staging..production`.',
            in: 'path',
            name: 'revision',
            required: true,
            schema: { type: 'string' },
          },
        }),
      workspace: z
        .string()
        .openapi({
          param: {
            description:
              'This can either be the workspace ID (slug) or the workspace UUID\nsurrounded by curly-braces, for example: `{workspace UUID}`.\n',
            in: 'path',
            name: 'workspace',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'When used, only one the diff of the specified file will be returned.',
            in: 'query',
            name: 'path',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: { description: 'The raw diff contents.' },
    403: {
      description: 'If the authenticated user does not have access to the snippet.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: {
      description: 'If the snippet does not exist.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ oauth2: ['snippet'] }, { basic: [] }, { api_key: [] }],
})

